function packageStoryboard(profile=false) {
 return {label:profile?'Perfil profissional':'Componente da Store',icon:profile?'profiles':'store',
 owner:profile?'Profile Pack / provisioning / activation / trust':'App Store / Component Manager / trust',start:'details',screens:{
 details:screen(profile?'Ferramentas que acompanham seu ofício.':'Conheça antes de adicionar.',profile?'Um perfil compõe ferramentas. Ele não troca sua identidade nem concede privilégios.':'O catálogo apresenta a oferta; o gerenciador e a política de trust decidem a instalação.','compatibility',{entity:true,rows:[row('Publisher','OrdaX · exemplo editorial, sem assinatura verificada'),row('Versão','0.1.0-preview · identificação fictícia'),row('Origem','Fixture do estudo, fora do catálogo publicado'),row('Alcance','Somente o Space selecionado')],nextLabel:'Revisar requisitos',actions:[action('Ver atualização','update'),action('Revisar remoção','remove')]}),
 compatibility:screen('Compatibilidade antes da promessa.','Módulos, modo do dispositivo e dependências precisam ser conferidos pelo owner.','permissions',{rows:[row('Modo','USB · exemplo'),row('Requisito','Referências de arquivos escolhidas'),row('Dispositivos','Autorização separada por capacidade')],nextLabel:'Revisar permissões',conditions:[action('Não compatível','incompatible'),action('Catálogo indisponível','unavailable'),action('Sem rede','offline'),action('Conteúdo não confiável','blocked')]}),
 permissions:screen('Instalar não é autorizar tudo.','Revise o que o componente pode solicitar. A execução continua sujeita aos grants e ao executor.','download',{confirm:'Revisei origem, requisitos e alcance no ensaio.',nextLabel:profile?'Ensaiar provisionamento':'Ensaiar instalação',rows:[row('Arquivos','Apenas referências selecionadas'),row('Rede / câmera / microfone','Nenhum acesso automático'),row('Contexto de IA','Revisão de fontes e saída ao provedor separada')],actions:[action('Não aprovar','denied')]}),
 denied:screen('Você manteve o controle.','O componente não foi ativado. A revisão pode ser retomada quando fizer sentido.','permissions',{nextLabel:'Reabrir revisão'}),
 download:screen('Recebendo o candidato.','Download ilustrativo; nenhum pacote é transferido.','verify',{phase:28,nextLabel:'Mostrar candidato recebido',conditions:[action('Interrupção','offline')]}),
 verify:screen('Verificando o que será ativado.','Publisher, artefato e assinatura precisam corresponder à identidade aceita.','stage',{phase:52,nextLabel:'Mostrar verificação aceita',conditions:[action('Assinatura recusada','blocked')]}),
 stage:screen('Preparando uma ativação separada.','O componente anterior continua disponível enquanto o candidato é preparado.','activate',{phase:70,nextLabel:'Mostrar preparação concluída',conditions:[action('Falha na preparação','failed')]}),
 activate:screen(profile?'Aplicando a composição ao Space.':'Ativando no cenário.','Uma ativação ainda precisa da confirmação de saúde. Não encerramos o fluxo como sucesso antes dela.','health',{phase:84,nextLabel:'Verificar saúde'}),
 health:screen('Confirmando a experiência.','O exemplo está sendo revisado antes de aparecer como disponível.','complete',{phase:94,nextLabel:'Mostrar saúde confirmada',conditions:[action('Saúde não confirmada','failed')]}),
 complete:screen(profile?'Perfil pronto no ensaio.':'Componente disponível no ensaio.',profile?'A composição visual está pronta. Comunidade e dispositivos permanecem opt-in.':'O roteiro foi concluído. Isso não adiciona software ao computador nem comprova disponibilidade de release.',null,{tone:'success',finish:'Voltar ao catálogo',result:'available',receipt:'Revisão → candidato → verificação → ativação → saúde · demonstração.',actions:[action('Configurar','configure'),action('Revisar remoção','remove'),action('Revisar atualização','update')],links:profile?[{label:'Comunidade do perfil',action:'journey:communication'}]:[]}),
 configure:screen('Ajuste sem ampliar privilégios.','Escolhas de apresentação da composição. Nenhuma permissão real é concedida.','complete',{fields:[choice('visibility','Visibilidade profissional',[['private','Somente eu'],['opt-in','Participar do diretório do Space · exemplo']],'private')],nextLabel:'Guardar escolha visual'}),
 update:screen('Uma mudança precisa de revisão.','Versão de exemplo 0.2.0-preview candidata. Dados existentes permanecem; a versão anterior é retida até health.','compatibility',{nextLabel:'Revisar atualização'}),
 remove:screen(profile?'Remover o perfil deste Space?':'Remover o componente deste Space?','Revise dependências e dados. Remover uma ferramenta não deve apagar documentos automaticamente.','removed',{confirm:'Entendi o impacto da remoção no ensaio.',nextLabel:'Ensaiar remoção',rows:[row('Arquivos e projetos','Preservados'),row('Ferramentas dependentes','Podem ficar indisponíveis'),row('Permissões','Revisadas separadamente pelo owner')]}),
 removed:screen('Remoção representada.','Nenhum software ou dado real foi removido. Você pode explorar a instalação novamente.',null,{finish:'Voltar ao catálogo',result:'removed',tone:'success',actions:[action('Revisar novamente','details')]}),
 offline:problem('Aguardando conexão.','Nenhuma fase de ativação foi confirmada. O trabalho existente continua disponível.','compatibility'),
 unavailable:problem('O catálogo não está disponível.','Não usamos uma entrada antiga como identidade verificada.','details'),
 incompatible:problem('O requisito não foi atendido.','Não é possível continuar a ativação neste cenário. Veja alternativas compatíveis no catálogo.','details'),
 blocked:problem('O candidato não é confiável.','A verificação recusou o componente. Nenhuma opção oferece ignorar a verificação.','details'),
 failed:screen('O candidato não ficou saudável.','A versão anterior permanece retida; o gerenciador deve apresentar o motivo e o resultado da recuperação.','retained',{tone:'warning',nextLabel:'Visualizar versão anterior retida'}),
 retained:screen('Seu trabalho continua disponível.','A ativação anterior foi preservada no ensaio. O candidato com falha não será reaplicado automaticamente.',null,{finish:'Voltar ao catálogo',receipt:'Falha retida · revisão necessária antes de nova tentativa',actions:[action('Rever requisitos','compatibility')]}),
 }};
}
